function NewChapter2D:GetAutoPlayState()
    return tonumber(CfUtils.GetLocalData("CHAPTER_AUTO_PLAY")) == 1
end

function NewChapter2D:GetAutoPlaySpeed()
    return tonumber(CfUtils.GetLocalData("CHAPTER_AUTO_PLAY_SPEED",1))
end

function NewChapter2D:SetAutoPlayBtnState()
    KTool.SetActive(self.BtnSpeed.gameObject, self.IsAutoPlay)
    if self.IsAutoPlay then
        self.isNeedClick = false
    end
    local state = self.IsAutoPlay and 2 or 1
    self.TgAuto.gameObject:GetComponent(typeof(UISwitchImage)).Status = state
    self._autoSpeed = self:GetAutoPlaySpeed()
    CS.UnityEngine.Time.timeScale = NewChapterConstants.SpeedUp[self._autoSpeed]
    DOTween.timeScale = NewChapterConstants.SpeedUp[self._autoSpeed]
    CriWareUtils.SetAudioSpeed(NewChapterConstants.SpeedUp[self._autoSpeed])
    self.BtnSpeed.transform:Find("ImgSpeed").gameObject:GetComponent(typeof(UISwitchImage)).Status = self._autoSpeed
end

function NewChapter2D:Start()
    SetButtonAction(self.BtnUIControl, function()
        self.IsUIHide = true
        self:SetVisible(true)
        self:SetUIState(true)
        KTool.SetActive(self.OverlayBtn.gameObject, true)
    end)

    --self.TgAuto.onValueChanged:AddListener(function(st)
    --    self.IsAutoPlay = st
    --    self:SetAutoPlay(st)
    --end)
    SetButtonAction(self.TgAuto, function()
        KTool.SetActive(self.BtnSpeed.gameObject, not self.IsAutoPlay)
        self.IsAutoPlay = not self.IsAutoPlay
        local value = self.IsAutoPlay and 1 or 0
        CfUtils.WriteLocalData("CHAPTER_AUTO_PLAY",value)
        if self.IsAutoPlay then
            self.isNeedClick = false
        end
        local state = self.IsAutoPlay and 2 or 1
        self.TgAuto.gameObject:GetComponent(typeof(UISwitchImage)).Status = state
        self._autoSpeed = 1
        CfUtils.WriteLocalData("CHAPTER_AUTO_PLAY_SPEED",self._autoSpeed)
        CS.UnityEngine.Time.timeScale = NewChapterConstants.SpeedUp[self._autoSpeed]
        DOTween.timeScale = NewChapterConstants.SpeedUp[self._autoSpeed]
        CriWareUtils.SetAudioSpeed(NewChapterConstants.SpeedUp[self._autoSpeed])
        self:SetAutoPlay(self.IsAutoPlay)
        self.BtnSpeed.transform:Find("ImgSpeed").gameObject:GetComponent(typeof(UISwitchImage)).Status = self._autoSpeed
    end)

    SetButtonAction(self.BtnSpeed, function()
        self._autoSpeed = self._autoSpeed % #NewChapterConstants.SpeedUp + 1
        CfUtils.WriteLocalData("CHAPTER_AUTO_PLAY_SPEED",self._autoSpeed)
        CS.UnityEngine.Time.timeScale = NewChapterConstants.SpeedUp[self._autoSpeed]
        DOTween.timeScale = NewChapterConstants.SpeedUp[self._autoSpeed]
        CriWareUtils.SetAudioSpeed(NewChapterConstants.SpeedUp[self._autoSpeed])
        self.BtnSpeed.transform:Find("ImgSpeed").gameObject:GetComponent(typeof(UISwitchImage)).Status = self._autoSpeed
    end)

    SetButtonAction(self.OverlayBtn, function()
        self.IsUIHide = false;
        self:SetVisible(false)
        self:SetUIState(false)
        if self.IsTyping then
            self._wait = false
        end

        KTool.SetActive(self.OverlayBtn.gameObject, false)
    end)

    SetButtonAction(self.BtnPlotReview, function()
        for i = #self.record, 1, -1 do
            if self.record[i] then
                if not isSet(self.record[i],"content") then
                    table.remove(self.record,i)
                else
                    if self.record[i].content == "" then
                       table.remove(self.record,i)
                    end
                end
            end
        end
        self.reviewEnv:Show(self.record)
    end)

    --self.BlockEmpty = false

    self._lateUpdater = Bind(self, self.OnLateUpdate)
    MonoHelper.AddLateUpdateListener(self._lateUpdater)

    -- 准备 字幕 配表数据:
    VideoSubtitleUtils.PrepareAllVOs()
end

function NewChapter2D:StopCo()

    printInfo("stop co")

    if self._waitCo ~= nil then
        cs_coroutine.stop(self._waitCo)
    end

    if self._dialogCo ~= nil then
        for i, v in pairs(self._dialogCo) do
            cs_coroutine.stop(v)
        end
    end
    if self._cachedLoader ~= nil then
        for i, v in pairs(self._cachedLoader) do
            cs_coroutine.stop(v)
        end
    end

    if self._cachedBgCo ~= nil then
        cs_coroutine.stop(self._cachedBgCo)
    end

    if self._delaySoundCo ~= nil then
        cs_coroutine.stop(self._delaySoundCo)
    end

    if self._soundDetectCo ~= nil then
        cs_coroutine.stop(self._soundDetectCo)
    end

    self:StopMessageCloseCo()

    if self.flashBackCo ~= nil then
        cs_coroutine.stop(self.flashBackCo)
        self.flashBackCo = nil
    end

    self:StopEntryTipCo()

    self._modifyBs = false
    self._modifyModel = nil

end

function NewChapter2D:StopMessageCloseCo()
    if self._messageCloseCo ~= nil then
        cs_coroutine.stop(self._messageCloseCo)
        self._messageCloseCo = nil
        KTool.SetActive(self.Message.gameObject,false)
        self.messageEnv:CleanMessageData()
    end
end

function NewChapter2D:OnLateUpdate()

    if not self._modifyBs or isNull(self._modifyModel) then
        return
    end

    --printInfo("will modify %s %s", tostring(self._modifyBs), tostring(table.dump(self._modifyModel)))

    for i, v in pairs(self._modifyModel) do

        --printInfo(table.dump(v.willModify))

        for ii, vv in pairs(v.willModify) do
            v.skinned:SetBlendShapeWeight(vv, 0)
        end

    end
    --printInfo("modify ")
end

function NewChapter2D:OnDestroy()
    -- 退出前关闭循环音效
    -- print("[声音] NewChapter2D 退出前关闭循环音效")
    if not isNull(self.soundRecord) then
        if not IsNull(self.soundRecord.loopSERecord) then
            for i, v in ipairs(self.soundRecord.loopSERecord) do
                CriWareUtils.StopById(v)
            end
        end
        if not isNull(self.soundRecord.bgmRecord) then
            for i, v in ipairs(self.soundRecord.bgmRecord) do
                CriWareUtils.StopById(v)
            end
        end
        if not isNull(self.soundRecord.SERecord) then
            for i, v in ipairs(self.soundRecord.SERecord) do
                CriWareUtils.StopById(v)
            end
        end
    end

    self:StopCo()
    if self._lateUpdater ~= nil then
        MonoHelper.RemoveLateUpdateListener(self._lateUpdater)
    end
    CS.UnityEngine.Time.timeScale = self.timeScaleBeforeChapter
    DOTween.timeScale = self.timeScaleBeforeChapter
    CriWareUtils.SetAudioSpeed(self.timeScaleBeforeChapter)
    NewChapterShared:DisposeAll()

    if not isNull(self.battleEnv) then
        self.battleEnv:DisposeAll()
        self.battleEnv = nil
    end

    printInfo("dispose all")

    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end


