function NewChapter2D:InitLayout()
    KTool.SetActive(self.DialogBtn.gameObject, false)
    KTool.SetActive(self.Dialog.gameObject, false)
    KTool.SetActive(self.ScreenBtn.gameObject, false)
    KTool.SetActive(self.OverlayBtn.gameObject, false)
    KTool.SetActive(self.Indicate.gameObject, false)
    KTool.SetActive(self.Text.gameObject, false)
    KTool.SetActive(self.Empty.gameObject, false)
    KTool.SetActive(self.sceneBg.gameObject,false)
end

function NewChapter2D:InitEffectPlane()
    local origin = 16 / 9
    local current = CS.Game.Native.URP.URPCameraController.Instance.uiCamera.aspect
    local xScale = current / origin
    local texName = "_MainTex"
    --self.effect.sharedMaterial:SetTexture(texName, GachaponShared:GetCapture());
    self.effect.sharedMaterial:SetTextureScale(texName, Vector2(xScale, 1));
    self.effect.sharedMaterial:SetTextureOffset(texName, Vector2((1 - xScale) / 2, 0));
end

function NewChapter2D:InitRealBg()
    local size = CSGameUtils.CalculateCameraViewSize(self.Camera3D, self.Camera3D.farClipPlane)
    local scale = self.realBg.transform.localScale
    scale.x = size.x
    scale.y = size.y
    self.realBg.transform.localScale = scale

    if self.UseRealBg then
        KTool.SetActive(self.realBg, true)
        KTool.SetActive(self.bg2D, false)
        KTool.SetActive(self.bg3D, false)
    end
end

function NewChapter2D:SetLoadingStatus(state)
    KTool.SetActive(self.Loading.gameObject,state)
end

function NewChapter2D:InitSpecialData(parameters)
    self.SpecialData = {}
    self.SpecialData.Mood = 0
    self.SpecialData.Options = {}
    self.RoleId = parameters.roleId
end

function NewChapter2D:GetSpecialData()
    self.SpecialData.Options = table.concat(self.SpecialData.Options, ",")
    return self.SpecialData
end

function NewChapter2D:SetUIState(st)

    KTool.SetActive(self.TgAuto.gameObject, not st)

    KTool.SetActive(self.BtnUIControl.gameObject, not st)

    KTool.SetActive(self.BtnSkip.gameObject, not st)

    KTool.SetActive(self.BtnPlotReview.gameObject, not st)

    KTool.SetActive(self.BtnSpeed.gameObject, not st)
    if not st then
        KTool.SetActive(self.BtnSpeed.gameObject, checkBool(self.IsAutoPlay))
    end
end

function NewChapter2D:SetAutoPlay(state)
    if state then
        if not self.IsTyping and not self.HasOption then
            printInfo("Invoke")
            self.ScreenBtn.onClick:Invoke()
        elseif self._endCo then
            printInfo("refresh")
            self:Refresh(self._cachedVo.nextId)
        end
    end
    self.IsAutoPlay = state
    printInfo("SetAutoPlay ")
    printInfo(state)
end

function NewChapter2D:SetVisible(state)
    self.IsVisible = state

    if state then
        self._preAuto = self.IsAutoPlay
        self.IsAutoPlay = false
    else
        self.IsAutoPlay = self._preAuto
        if self.IsAutoPlay then
            self:SetAutoPlay(self.IsAutoPlay)
        end
    end
    --self:FinishType()
    KTool.SetActive(self.Dialog.gameObject, not state)
    --KTool.SetActive(self.Option, not state)
    printInfo("SetVisible ")
    printInfo(state)
end

function NewChapter2D:SpecialSkip()

    local id = self.GeneralVo.startId
    if self._cachedVo ~= nil then
        if  NewChapterUtils.HasOption(self._cachedVo) then
            return
        end
        id = self._cachedVo.id
    end

    local vo = self:FindNextOption(id)
    if vo == nil then
        self:SkipAll()
    else
        self:StopCo()

        if self._cachedVo ~= nil then
            self._endCo = true
            self.HasOption = false

            KTool.SetActive(self.Empty, false)
            self.TxtContent1:SetText("")
            self.TxtContent2:SetText("")
            self.TxtLeftName.text = ""
            self:ClearScreenText()
            self:ClearNormalText()
            self:ClearOption()
            self:ResetArgs()
            self:ReposCharacters()
            self:ClearEvents()
            self:StopSE(self._cachedVo)
        end

        self._cachedLoader = {}
        self._cachedVo = vo
        if self.recordCell == nil then
            self.recordCell = {}
        end
        local wait = self:ClearScreenEffect(true)
        if wait ~= nil and next(wait) ~= nil then
            for i = 1, #wait do
                cs_coroutine.stop(wait[i])
            end
        end

--[[        local wait = self:ClearBeforeScreenEffect(true)
        if wait ~= nil and next(wait) ~= nil then
            for i = 1, #wait do
                coroutine.yield(wait[i])
            end
        end]]

        KTool.SetActive(self.Block, false)
        self:Refresh(vo.id)
    end
end

function NewChapter2D:FindNextOption(id)
    ---@type NewChapter2DVo
    local vo = self.DialogSetting:Get(id)
    if NewChapterUtils.HasOption(vo) then
        return vo
    end
    if vo.nextId == 0 then
        return nil
    else
        return self:FindNextOption(vo.nextId)
    end
end

function NewChapter2D:SkipAll()
    self.summaryEnv:Show(self.GeneralVo, nil, function()
        if self._isSkip then
            return
        end
        self._isSkip = true
        --if not isNull(self.CsEnv) then
        --    self.CsEnv:ChapterFinish()
        --end
        self:StopCo()
        if self.FinishCall ~= nil then
            self.FinishCall()
        end

        xRecord.record(ChapterConstants.EventId, string.format(ChapterConstants.EventContent, self.ChapterId))
    end)

end

function NewChapter2D:FinishType()
    if self.IsTyping then
        self._wait = false
    end
end

function NewChapter2D:ResetArgs()
    self._splitlineEffect = false
    self._blockWait = 0
end

function NewChapter2D:SetHeadStatus(state)
    KTool.SetActive(self.IconHead.transform.parent.gameObject, state)
    KTool.SetActive(self.IconHead.gameObject, state)
end

---@param vo NewChapter2DVo
function NewChapter2D:SetIconHead(vo)
    self:StopHeadEffect(vo.headEffect)
    if not string.isEmpty(vo.characterId) and vo.exist == 0 then
        self:SetHeadStatus(false)
        return
    end

    local icon = vo.avatar


    if string.isEmpty(icon) then
        self:SetHeadStatus(false)
        return
    end

    if not KTool.IsActiveInHierarchy(self.IconHead.transform.parent.gameObject) then
        KTool.SetActive(self.IconHead.transform.parent.gameObject, true)
    end

    if not KTool.IsActiveInHierarchy(self.IconHead.gameObject) then
        KTool.SetActive(self.IconHead.gameObject, true)
    end

    if self._cachedHead == icon then
        if vo.headEffect > 0 then
            self:StartHeadEffect(vo.headEffect)
        end
        return
    end

    self._cachedHead = icon
    printInfo("SetIconHead %s", icon)

    KTool.SetActive(self.IconHead, false)

    self.IconHead.OnFinish = function()
        KTool.SetActive(self.IconHead, true)
        if vo.headEffect > 0 then
            self:StartHeadEffect(vo.headEffect)
        end
    end

    self.IconHead.isNativeSize = false
    self.IconHead:LoadSprite(icon, ChapterConstants.ChapterPool)

end

function NewChapter2D:StartHeadEffect(headEffect)
    if self.cacheHeadEffect and self.cacheHeadEffect == headEffect then
        return
    end
    self.cacheHeadEffect = headEffect
    if headEffect == NewChapterConstants.HeadEffect.PhoneCall then
        local material = self.IconHead.image.material
        material:SetInt("_UseCommunication",1)
        CfUtils.SetActive(self.InCommunication.gameObject,true)
    elseif headEffect == NewChapterConstants.HeadEffect.HeadMemory then
        local material = self.IconHead.image.material
        material:SetInt("_UseMemoryEffect",1)
        CfUtils.SetActive(self.InCommunication.gameObject,false)
    end
end

function NewChapter2D:StopHeadEffect(headEffect)
    if self.cacheHeadEffect then
        if  self.cacheHeadEffect ~= headEffect  then
            if self.cacheHeadEffect == NewChapterConstants.HeadEffect.PhoneCall then
                local material = self.IconHead.image.material
                material:SetInt("_UseCommunication",0)
                CfUtils.SetActive(self.InCommunication.gameObject,false)
            elseif self.cacheHeadEffect == NewChapterConstants.HeadEffect.HeadMemory then
                local material = self.IconHead.image.material
                material:SetInt("_UseMemoryEffect",0)
            end
            self.cacheHeadEffect = nil
        end
    else
        ---这个属性会被保存下来  这里做一下强制清除
        local material = self.IconHead.image.material
        material:SetInt("_UseCommunication",0)
        material:SetInt("_UseMemoryEffect",0)
        CfUtils.SetActive(self.InCommunication.gameObject,false)
    end
end

function NewChapter2D:SetContentName(owner)
    assert(type(owner) == "string")
    --self.TxtLeftName.text = owner
    --KTool.SetActive(self.LeftTitle.gameObject, not string.isEmpty(owner))
    local st = not string.isEmpty(owner)
    KTool.SetActive(self.Titles.gameObject, st)
    if st then
        self.TxtLeftName.text = owner
    end
end

function NewChapter2D:SetButtonClick(button, callback)
    if button and button.onClick then
        button.onClick:RemoveAllListeners()
        button.onClick:AddListener(callback)
    else
        print("set click event failed ,type not button")
    end
end

function NewChapter2D:Refresh(id, isSubId)
    assert(type(id) == "number")
    printInfo("ChapterDialog:Refresh " .. tostring(id))

    if id == 0 then
        --self.controller:Close()
        Events.Broadcast(ChapterConstants.ChapterEvents.OnChapterEndDialog)

        --KTool.SetActive(self.Dialog, false)

        --KTool.SetActive(self.DialogBtn, false)
        --self.Tween = self.Dialog.gameObject:GetComponent(typeof(CanvasGroup)):DOFade(0, 0.25)

        self:StopCo()
        --self.CsEnv:ResumeDirector()
        if self.FinishCall ~= nil then
            self.FinishCall()
        end

        return
    end

    if self.record == nil then
        self.record = {}
    end

    if isSubId == nil then
        isSubId = false
    end

    if not isSubId then
        self._endCo = false
        self.BlockClick = false
    end

    self.GotoNext = nil

    if isNull(self._dialogCo) then
        self._dialogCo = {}
    end

    self._dialogCo[id] = cs_coroutine.start(function()
        if self == nil or self.DialogSetting == nil then
            return
        end
        ---@type NewChapter2DVo
        local currentDialog = self.DialogSetting:Get(id)
        if currentDialog == nil then
            printError("%d not found %d", self.ChapterId, id)
            return
        end
        currentDialog:SetupPath(self.GeneralVo.is2d)
        print("dialog ",table.dump(currentDialog))
        if not isSubId then
            self._cachedVo = currentDialog
        end

        if not isSubId then
            KTool.SetActive(self.Camera3D.gameObject, not currentDialog.Is2D)
            KTool.SetActive(self.Camera2D.gameObject, currentDialog.Is2D)
        end

        if not isSubId then
            if currentDialog.usage == NewChapterConstants.SpecialFunc.HideSkipBtn then
                KTool.SetActive(self.BtnSkip.gameObject, false)
            else
                KTool.SetActive(self.BtnSkip.gameObject, true)
            end

            if self._lockName then
                KTool.SetActive(self.BtnSkip.gameObject, false)
            end

            if self.IsVisible then
                KTool.SetActive(self.BtnSkip.gameObject, false)
            end
        end

        self:ProcessMusic(currentDialog)

        if not isSubId then
            if currentDialog.type == NewChapterConstants.NewType.LoadingFirst or currentDialog.type == NewChapterConstants.NewType.LoadingSecond then
                self:SetLoadingStatus(true)
                cs_coroutine.yield_return(self.loadingEnv:RefreshShow(currentDialog))
                self:Refresh(currentDialog.nextId)
                return
            end
        end

        if NewChapterConstants.BeforeCleanCharacter[currentDialog.screenAnim] then
            self:ClearPrevCharacters(currentDialog)
        end

        if not isSubId and self.GeneralVo.is2d ~= 3 then
            self:StartMoveCamera(currentDialog)
        end

        if not isSubId then
            KTool.SetActive(self.maskBg.gameObject,self.GeneralVo.is2d == 3)
            if self.GeneralVo.is2d ~= 3 then
                self:LoadBg(currentDialog)
                self:LoadSceneBg(currentDialog)
                self:BgBlur(currentDialog)
                self:BgOffsetScale(currentDialog)
            end
        end

        if not isSubId then
            local wait = self:ClearScreenEffect()
            if wait ~= nil and next(wait) ~= nil then
                for i = 1, #wait do
                    coroutine.yield(wait[i])
                end
            end
        end

        if not isSubId then
            if currentDialog.type == NewChapterConstants.NewType.StartAnimation then
                self:StartMovie(currentDialog)
            end
        end

        if not isSubId then
            if currentDialog.battleGroupId ~= "" then
                self:StarBattle(currentDialog)
            end
        end

        if not isSubId then
            ---屏幕特效和文字同时？
            if currentDialog.screenAnim ~= NewChapterConstants.ScreenEffect.None then
                ---有些效果要等到图片加载出来之后  所以这里不处理  --当SceneId为空的时候 图片是不会被加载 所以有些效果 在图片的加载后执行的 并不会被执行 所以加上这个判定
                if not NewChapterConstants.SceneEffectImmediatelyBg[currentDialog.screenAnim] then
                    self:StartScreenEffect(currentDialog)
                end
            end
        end

        if not isSubId then
            self:StartEntryTip(currentDialog)
        end


        if not isSubId then
            if not NewChapterConstants.BeforeCleanCharacter[currentDialog.screenAnim] then
                self:ClearPrevCharacters(currentDialog)
            end

            self:ClearCharacterEffect(currentDialog)

            self:RecordText(currentDialog)
        end
        self:SetIconHead(currentDialog)
        self:CharacterEnter(currentDialog)

        coroutine.yield(self:LoadCharacter(currentDialog))

        KTool.SetActive(self.Control.gameObject,true)

        self:ProcessSE(currentDialog)

        if not isSubId then
            if currentDialog.messageId ~= 0 then
                if currentDialog.messageId ~= -1 then
                    -- 上一段消息可能还在播放延迟关闭动画，启动新消息前必须取消它，
                    -- 否则关闭协程会清理并停止本次 StartMessage 的协程。
                    self:StopMessageCloseCo()
                    KTool.SetActive(self.Message.gameObject,true)
                    if not isNull(self.messageEnv) then
                        coroutine.yield(self.messageEnv:StartMessage(currentDialog.messageId))
                        self._endWait = true
                    end
                end
            else
                if self.Message.gameObject.activeSelf then
                    self:StopMessageCloseCo()
                    self._messageCloseCo = cs_coroutine.start(function()
                        self.messageEnv:PlayAni("ChapterNormal_ChapterNewUI_Message_Out")
                        coroutine.yield(Yielders.GetWaitForSeconds(0.4))
                        KTool.SetActive(self.Message.gameObject,false)
                        self.messageEnv:CleanMessageData()
                        self._messageCloseCo = nil
                    end)
                end
            end
        end

        if not isSubId then
            if self:ClearAndCheck(currentDialog) then
                self:StartText(currentDialog)
            end
        end

        if not isSubId then
            if currentDialog.type == NewChapterConstants.NewType.FlashBack then
                self:LoadFlashBackImage(currentDialog)
                return
            end
        end

        --self._cachedVo = currentDialog
        --角色到位

        if not isSubId then
            if string.isEmpty(currentDialog.displayItem) then
                self.BlockAuto = false
                KTool.SetActive(self.item.transform.parent.gameObject, false)
            else
                --coroutine.yield(self:ProcessItem(currentDialog))
                self:ProcessItem(currentDialog)
            end
        end

        if self._endWait ~= nil and self._endWait then
            if not KTool.IsActiveInHierarchy(self.ScreenBtn.gameObject) then
                KTool.SetActive(self.ScreenBtn.gameObject, true)
            end

            self:SetButtonClick(self.ScreenBtn, function()
                if self.BlockClick then
                    return
                end
                self.ScreenBtn.onClick:RemoveAllListeners()

                if not self.IsAutoPlay then
                    --self:Refresh(vo.nextId)
                    self.GotoNext = currentDialog.nextId
                end

                --printInfo("DialogBtn")

                self._endWait = false
            end)

            if self.IsAutoPlay then
                self._endWait = false
            end

            while self._endWait do
                coroutine.yield()
            end

            KTool.SetActive(self.ScreenBtn.gameObject, false)
        end

        if currentDialog.type ~= NewChapterConstants.NewType.StartCgPlay then
            if KTool.IsActiveInHierarchy(self.cg.gameObject) then
                KTool.SetActive(self.cg.gameObject, false)
            end
        end

        --if currentDialog.type == NewChapterConstants.NewType.ChapterOption then
        if NewChapterUtils.HasOption(currentDialog) then
            self:ClearScreenText()
        end



        self:ResetArgs()

        --currentDialog.faceId = ""
        --currentDialog.action = ""
        --self:SetCharacterState(currentDialog, true)

        self:ReposCharacters()

        self:ClearEvents()
        --self.recordCell = nil

        self._finishCall = nil

        self._dialogCo[id] = nil

        if not isSubId then
            if (self.IsAutoPlay and not self.HasOption) and not self.BlockAuto then
                printInfo("IsAutoPlay Invoke")
                if string.isEmpty(currentDialog.voice) then
                    coroutine.yield(Yielders.GetWaitForSeconds(NewChapterConstants.AutoPlayWaitTime))
                else
                    while not self.voiceFinish do
                        coroutine.yield()
                    end
                end
                if self.GotoNext == nil then
                    self.GotoNext = currentDialog.nextId
                end
            end
        end

        self:StopSE(currentDialog)

        if not isSubId then
            self._endCo = true

            self.HasOption = false

            if self.GotoNext ~= nil then
                self:Refresh(self.GotoNext)
            end
        end
    end)
end

function NewChapter2D:FillPlaceHold(origin)
    if string.isEmpty(origin) then
        return origin
    end

    local playerComp = ChapterUtils.GetPlayerComp()
    local result = origin
    result = ChapterUtils.ReplaceStr(result, "#playerName", playerComp.playerDojo.playerName)
    result = ChapterUtils.ReplaceStr(result, "#playerId", playerComp.playerDojo.playerId)
    result = ChapterUtils.ReplaceStr(result, "/n", "\n")

    if CS.Engine.I18N.I18NModule.Lang ~= "en_US" and CS.Engine.I18N.I18NModule.Lang ~= "en_UK" then
        result = ChapterUtils.ReplaceStr(result, " ", NonBreakingSpace)
    end

    --if isSet(ChapterConstants.ChapterScheme, ownerId) then
    --    result = string.format(ChapterConstants.ChapterScheme[ownerId].scheme, result)
    --end

    return result
end

---@param vo NewChapter2DVo
function NewChapter2D:RecordText(vo)
    if not NewChapterUtils.HasOption(vo) then
        self.recordCell = {}
        self.recordCell.owner = self:GetChapterName(vo)
        table.insert(self.record, self.recordCell)
    end

end

function NewChapter2D:GetChapterName(vo)
    local chapterName = self.gender == Constants.PLAYER_GENDER.FEMALE and vo.feCharacterName or vo.characterName
    if string.isEmpty(chapterName) then
        chapterName = vo.characterName
    end
    local chapterName = self:FillPlaceHold(chapterName)

    return chapterName
end
---这个类型要自动跳过  所以执行顺序不能靠前  会影响其他的逻辑处理
function NewChapter2D:LoadFlashBackImage(vo)
    if vo.flashBackTime ~= 0 then

        if self.flashBackCo ~= nil then
            cs_coroutine.stop(self.flashBackCo)
            self.flashBackCo = nil
        end

        local wait = true
        self.flashBackCo = cs_coroutine.start(function()
            coroutine.yield(Yielders.GetWaitForSeconds(vo.flashBackTime))
            wait = false
        end)

        while wait do
            coroutine.yield()
        end

        if self.flashBackCo ~= nil then
            cs_coroutine.stop(self.flashBackCo)
        end
        self.flashBackCo = nil
        self:Refresh(vo.nextId)
    else
        self:Refresh(vo.nextId)
    end
end

function NewChapter2D:StartMoveCamera(vo)
    local index
    local time

    if not isNull(vo.moveCamera) and table.count(checkTable(vo.moveCamera)) > 0 then
        index = vo.moveCamera[1]
        time = vo.moveCamera[2] or 0
    else
        index = 0
        time = 0
    end
    if self.lastIndex and self.lastIndex == index then
        return
    end
    self.lastIndex = index
    self:CleanCameraTween()
    if index == 0 then
        local posVo = CfUtils.GetCfVo(AutoIds.IdSetting4104, "ChapterCamMovePosVo", 1)
        if not isNull(posVo) then
            self.Camera3D.transform.localPosition = posVo.Transform
            ---这里要把特效相机也移动一下 防止一些效果对不上 比如通讯
            self.CameraEffect.transform.localPosition = posVo.Transform
        end
    else
        if index > 0 then
            local posVo = CfUtils.GetCfVo(AutoIds.IdSetting4104, "ChapterCamMovePosVo", index)
            if not isNull(posVo) then
                local pos = posVo.Transform
                if pos then
                    if time == 0 then
                        self.Camera3D.transform.localPosition = pos
                        ---这里要把特效相机也移动一下 防止一些效果对不上 比如通讯
                        self.CameraEffect.transform.localPosition = pos
                    else
                        self.cameraTween = self.Camera3D.transform:DOMove(pos,time)
                        ---这里要把特效相机也移动一下 防止一些效果对不上 比如通讯
                        self.CameraEffect.transform.localPosition = pos
                    end
                end
            end
        else
            printError("move camera 参数配置错误 配置 ！！！")
        end
    end
end

function NewChapter2D:CleanCameraTween()
    if not isNull(self.cameraTween) then
        self.cameraTween:Kill()
        self.cameraTween = nil
    end
end

---@param vo NewChapter2DVo
function NewChapter2D:StartText(vo)
    printInfo("start text %d", vo.type)
    if vo.type == NewChapterConstants.NewType.BlockText then
        coroutine.yield(self:StartScreenText(vo))
    elseif vo.type == NewChapterConstants.NewType.BlockTextTyped then
        coroutine.yield(self:StartScreenText(vo, true))
    elseif NewChapterUtils.HasOption(vo) then
        coroutine.yield(self:StartOption(vo))
        --self:StartOption(vo)
    else
        coroutine.yield(self:StartNormalText(vo))
    end
end

---@param vo NewChapter2DVo
function NewChapter2D:ClearAndCheck(vo)
    if vo.type == NewChapterConstants.NewType.BlockText or vo.type == NewChapterConstants.NewType.BlockTextTyped then
        self:ClearScreenText()
        KTool.SetActive(self.Empty.gameObject, false)
        return not string.isEmpty(vo.desc)
    elseif NewChapterUtils.HasOption(vo) then
        self:ClearOption()
        return not string.isEmpty(self:GetOption(vo))
    else
        self:ClearNormalText()
        KTool.SetActive(self.Dialog.gameObject, false)
        self:ClearScreenText()

        if not NewChapterConstants.SceneIgnoreEffect[vo.screenAnim] then
            KTool.SetActive(self.Empty.gameObject, false)
        end

        return not string.isEmpty(vo.desc)
    end
end

---@param vo NewChapter2DVo
function NewChapter2D:StartScreenText(vo, isType)
    if isType == nil then
        isType = false
    end
    assert(type(isType) == "boolean")

    if not KTool.IsActiveInHierarchy(self.Empty.gameObject) then
        KTool.SetActive(self.Empty.gameObject, true)
    end

    local black = self.Empty:Find("ImgBlack").gameObject:GetComponent(typeof(ImageComp))
    if not KTool.IsActiveInHierarchy(black.gameObject) then
        KTool.SetActive(black.gameObject, true)
    end

    if not KTool.IsActiveInHierarchy(self.Text.gameObject) then
        KTool.SetActive(self.Text.gameObject, true)
    end

    if not KTool.IsActiveInHierarchy(self.ScreenBtn.gameObject) then
        KTool.SetActive(self.ScreenBtn.gameObject, true)
    end

    local wait = true

    self:SetButtonClick(self.ScreenBtn, function()
        wait = false
    end)

    local desc = self:GetDesc(vo)
    local content = self:FillPlaceHold(desc)
    self.recordCell.content = content
    self.Text.text = ""
    if isType then
        local tween = self.Text:DOText(content, NewChapterConstants.BlockTextTypeParam.Time):SetEase(NewChapterConstants.BlockTextTypeParam.Ease)
        self.IsTyping = true
        self._waitCo = cs_coroutine.start(function()
            coroutine.yield(Yielders.GetWaitForSeconds(NewChapterConstants.BlockTextTypeParam.Time))
            wait = false
        end)

        while wait do
            coroutine.yield()
        end
        if self._waitCo ~= nil then
            cs_coroutine.stop(self._waitCo)
        end
        self._waitCo = nil
        tween:Complete()
        self.IsTyping = false
    end
    self.Text.text = desc
    coroutine.yield(Yielders.GetWaitForSeconds(NewChapterConstants.BlockTextTypeParam.EndWait))
    if self.IsAutoPlay then
        wait = false
    end

    while wait do
        coroutine.yield()
    end

    self._endWait = true
    self.ScreenBtn.onClick:RemoveAllListeners()
    self.GotoNext = vo.nextId
end

function NewChapter2D:GetDesc(vo)
    local desc = self.gender == Constants.PLAYER_GENDER.FEMALE and vo.feDesc or vo.desc
    if string.isEmpty(desc) then
        desc = vo.desc
    end
    return desc
end

function NewChapter2D:ClearScreenText()
    if KTool.IsActiveInHierarchy(self.ScreenBtn.gameObject) then
        KTool.SetActive(self.ScreenBtn.gameObject, false)
    end

    if KTool.IsActiveInHierarchy(self.Text.gameObject) then
        KTool.SetActive(self.Text.gameObject, false)
    end
end

---@param vo NewChapter2DVo
function NewChapter2D:StartNormalText(vo)
    local typeLetter = vo.type ~= NewChapterConstants.NewType.ChapterDirectText
    local showShake = vo.type == NewChapterConstants.NewType.ShakeTxt
    self.TxtContent1:SetText("", false)
    self.TxtContent2:SetText("", false)
    KTool.SetActive(self.Indicate.gameObject, false)

    --vo.desc = "出门左拐，去关卡名字，/n找那个boss名字，干他，抢他的西红柿"
    local desc = self:GetDesc(vo)

    local content = self:FillPlaceHold(desc)
    local str = string.split(content,"_n")

    if #str > 1 then
        self.recordCell.content = table.concat({str[1],str[2]})
    else
        self.recordCell.content = content
    end


    KTool.SetActive(self.grid.gameObject, false)

    local chapterName = self:GetChapterName(vo)
    self:SetContentName(chapterName)

    local active = not string.isEmpty(content)

    if not KTool.IsActiveInHierarchy(self.Dialog.gameObject) and active then
        printInfo("fade ")
        self.Dialog.gameObject:GetComponent(typeof(CanvasGroup)):DOFade(1, 0.25)
    end
    printInfo("active %s", tostring(active))
    KTool.SetActive(self.Dialog.gameObject, active)
    KTool.SetActive(self.TxtContent1.gameObject, active)
    KTool.SetActive(self.TxtContent2.gameObject, #str > 1)
    if self.IsVisible then
        KTool.SetActive(self.Dialog.gameObject, false)
        KTool.SetActive(self.TxtContent1.gameObject, false)
        KTool.SetActive(self.TxtContent2.gameObject, false)
    end

    self._endWait = true

    if not active then
        return
    end

    self.IsTyping = true
    ---是否需要点击 才跳转到下一句
    self.isNeedClick = (#str > 1 and not self.IsAutoPlay) and true or false

    local dialogClick = function()
        if self.BlockClick then
            return
        end
        self.DialogBtn.onClick:RemoveAllListeners()

        ---如果Str大于1  说明有2段播放 这里点击要跳下一段 不能结束
        if not self.IsAutoPlay and not self.isNeedClick then
            self:FinishType()
        end
        self.isNeedClick = false
        --printInfo("DialogBtn")
    end

    self:SetButtonClick(self.DialogBtn, dialogClick)
    KTool.SetActive(self.DialogBtn.gameObject, true)

    if showShake then
        coroutine.yield()
        self.Frames.transform:DOShakePosition(0.7, Vector3.New(20,20,0), 30, 2):OnComplete(function() end)
    end

    self._wait = true
    self._waitCo = cs_coroutine.start(function()
        for i = 1, #str do
            local txtContent = self["TxtContent"..i]
            if txtContent then
                txtContent.AppearDuration = 0.2
                txtContent.PendingTime = 0.05
                txtContent.TextWillFill = self:FillPlaceHold(str[i])
                txtContent.SplitlineEffect = self._splitlineEffect
                if typeLetter or showShake then
                    coroutine.yield(txtContent:StartType())
                else
                    txtContent:SetText(self:FillPlaceHold(str[i]), true)
                end

                while self.isNeedClick do
                    coroutine.yield()
                end
            end
        end
        self._wait = false
    end)

    while self._wait do
        coroutine.yield()
    end

    if self._waitCo ~= nil then
        cs_coroutine.stop(self._waitCo)
    end
    self._waitCo = nil

    if isNull(self.TxtContent1:GetTextComp()) or isNull(self.TxtContent2:GetTextComp()) then
        return
    end

    self.TxtContent1:StopType()
    self.TxtContent1:ShowAll()
    self.TxtContent2:StopType()
    self.TxtContent2:ShowAll()
    printInfo("finish type")
    self.IsTyping = false
    self:ClearNormalText()
end

function NewChapter2D:ClearNormalText()
    KTool.SetActive(self.Indicate.gameObject, true)
    if KTool.IsActiveInHierarchy(self.ScreenBtn.gameObject) then
        KTool.SetActive(self.ScreenBtn.gameObject, false)
    end
end

function NewChapter2D:GetOption(vo)
    local option = self.gender == Constants.PLAYER_GENDER.FEMALE and vo.feOption or vo.option
    if string.isEmpty(option) then
        option = vo.option
    end
    return option
end

---@param vo NewChapter2DVo
function NewChapter2D:StartOption(vo)
    if not KTool.IsActiveInHierarchy(self.Dialog.gameObject) then
        KTool.SetActive(self.Dialog.gameObject, true)
    end
    self.recordCell.option = {}
    if self.recordOption == nil then
        self.recordOption = {}
    end
    local option = self:GetOption(vo)
    local len = #option
    if len > 0 then
        self.HasOption = true;
        local wait = true
        for i = 1, self.grid.childCount do
            local btn = self.grid:GetChild(i - 1).gameObject:GetComponent(typeof(ButtonComp))
            local st = i <= len
            if vo.type == NewChapterConstants.NewType.RecordChapterOption then
                if isSet(self.recordOption, vo.id) and isSet(self.recordOption[vo.id], i) then
                    st = false
                end
            end
            KTool.SetActive(btn.gameObject, st)
            if st then
                local group = btn.transform:Find("Option").gameObject:GetComponent(typeof(CanvasGroup))
                group.alpha = 1
                local content = nil
                if not self.NeedSpecialData then
                    content = self:FillPlaceHold(option[i])
                else
                    printInfo(option[i])
                    ---@type NewChapterOptionVo
                    local optionVo = self.OptionSetting:Get(option[i])
                    content = self:FillPlaceHold(optionVo.desc)
                end
                table.insert(self.recordCell.option, content)
                btn.transform:GetChild(0):Find("Text"):GetComponent(typeof(TextComp)).text = content
                self:SetButtonClick(btn, function()
                    if self.BlockClick then
                        return
                    end
                    self.BlockClick = true
                    self.DialogBtn.onClick:RemoveAllListeners()
                    self.recordCell.selectIndex = i
                    if self.NeedSpecialData then
                        local optionId = option[i]
                        local mood = string.isEmpty(vo.friendship) and 0 or vo.friendship[i]
                        local prev = self.SpecialData.Mood
                        self.SpecialData.Mood = self.SpecialData.Mood + mood
                        self.SpecialData.Mood = math.max(self.SpecialData.Mood , -100)
                        self.SpecialData.Mood = math.min(self.SpecialData.Mood, 100)
                       -- self.moodEnv:SetValue(self.SpecialData.Mood, self.SpecialData.Mood - prev)
                        printInfo("optionId %d mood %d", optionId, self.SpecialData.Mood)
                        table.insert(self.SpecialData.Options, optionId)
                    end
                    self.GotoNext = checkNumber(vo.jumpId[i])
                    wait = false
                    if vo.type == NewChapterConstants.NewType.RecordChapterOption then
                        if not isSet(self.recordOption, vo.id) then
                            self.recordOption[vo.id] = {}
                        end
                        local t = self.recordOption[vo.id]
                        t[i] = 1
                    end
                end)
            end


        end

        KTool.SetActive(self.grid.gameObject, true)
        self.DialogBtn.onClick:RemoveAllListeners()
        KTool.SetActive(self.DialogBtn.gameObject, false)

        while wait do
            coroutine.yield(Yielders.EndOfFrame)
        end

        for i = 1, self.grid.childCount do
            local anim = self.grid:GetChild(i - 1)
            if KTool.IsActiveInHierarchy(anim.gameObject) then
                anim = anim:Find("Option").gameObject:GetComponent(typeof(Animator))
                local name = i == self.recordCell.selectIndex and "Out" or "Out2"
                anim:Play(name)
            end
        end

        coroutine.yield(Yielders.GetWaitForSeconds(0.5))

        self.BlockClick = false
        self:ClearOption()
        self._endWait = false
    end
end


function NewChapter2D:ClearOption()
    KTool.SetActive(self.grid.gameObject, false)
end

---@param vo NewChapter2DVo
function NewChapter2D:StartScreenEffect(vo)
    ---在Bg图之前的效果  不走这个
    --if NewChapterConstants.SceneEffectBeforeBg[vo.screenAnim] then return end

    self.DialogBtn.onClick:RemoveAllListeners()

    KTool.SetActive(self.ScreenBtn.gameObject, true)

    local wait = true

    self:SetButtonClick(self.ScreenBtn, function()
        if self.BlockClick then
            return
        end
        self.ScreenBtn.onClick:RemoveAllListeners()
        KTool.SetActive(self.ScreenBtn.gameObject, false)
        wait = false
    end)

    local effect, isImage = self:GetScreenEffect(vo)
    local co, object
    if effect ~= nil and isImage ~= nil then
        object = self:GetObjectByIsImage(isImage,vo)
        effect:StartEffect(object)
        printInfo("start effect %d", vo.screenAnim)
        co = cs_coroutine.start(function()
            while not effect:IsFinish() do
                coroutine.yield(Yielders.EndOfFrame)
            end
            wait = false
        end)
    else
        printError("no screen effect")
    end

    local effCo = nil
    if self.IsAutoPlay then
        effCo = cs_coroutine.start(function()
            coroutine.yield(Yielders.GetWaitForSeconds(NewChapterConstants.AutoPlayTime))
            wait = false
        end)
    end

    while wait do
        coroutine.yield(Yielders.EndOfFrame)
    end

    if effCo ~= nil then
        cs_coroutine.stop(effCo)
    end

    coroutine.yield(Yielders.GetWaitForSeconds(NewChapterConstants.ScreenEffectEndWait))
    if co ~= nil then
        cs_coroutine.stop(co)
    end

    if effect ~= nil and object ~= nil then
        effect:EndEffect(object)
        if vo.screenTime < 0 then
            printInfo("remove sametime")
            effect:RemoveEffect(object)
        else
            local tb = {}
            tb.effect = effect
            tb.parameters = object
            tb.time = vo.screenTime
            if self._cachedScreen == nil then
                self._cachedScreen = {}
            end
            self._cachedScreen[vo.screenAnim] = tb
        end
    end
    self.GotoNext = vo.nextId
end

function NewChapter2D:GetObjectByIsImage(isImage,vo)
    local object
    if isImage == NewChapterConstants.ScreenEffectType.Image then
        object = self.Empty:Find("ImgBlack")
    elseif isImage == NewChapterConstants.ScreenEffectType.SceneCamera then
        object = vo.Is2D and self.Camera2D or self.Camera3D
    elseif isImage == NewChapterConstants.ScreenEffectType.UICamera then

    elseif isImage == NewChapterConstants.ScreenEffectType.FullBlock then
        object = self.Block:Find("BlockScreen")
    elseif isImage == NewChapterConstants.ScreenEffectType.Bg then
        object = vo.Is2D and self.bg2D or self.bg3D
    end
    return object
end

---@param vo NewChapter2DVo
---@return BaseEffect, number
function NewChapter2D:GetScreenEffect(vo)
    local script, isImage = NewChapterShared:GetScreenEffect(vo.screenAnim)
    if script == nil then
        printError("%s not impl", tostring(vo.screenAnim))
        return nil, nil
    end
    script:Initialize(vo)
    return script, isImage
end

function NewChapter2D:ClearScreenEffect(force)
    if self._cachedScreen == nil then
        return
    end

    local remove = {}
    local wait = {}
    --self.BlockEmpty = false
    for i, v in pairs(self._cachedScreen) do
        v.time = v.time - 1

        if v.time < 0 or force then
            printInfo("remove")
            local co = v.effect:RemoveEffect(v.parameters)
            if co ~= nil then
                table.insert(wait, co)
            end
            table.insert(remove, i)
        else
            --self.BlockEmpty = true
        end
    end

    for i = 1, #remove do
        self._cachedScreen[remove[i]] = nil
    end
    return wait
end

