---@param vo NewChapter2DVo
---@param pos number @characterIndex
function NewChapter2D:StartCharacterEffect(vo, pos)
    if string.isEmpty(vo.effect) then
        return
    end
    local script = self:GetCharacterEffect(vo, pos)
    if script == nil then
        return
    end

    for i = 1, #script do
        if not string.isEmpty(script[i]) then
            local effType = script[i].type
            printInfo("start character " .. effType)
            if self._cachedCharEffect == nil then
                self._cachedCharEffect = {}
            end
            local key = vo.characterPath[pos] .. "+" .. effType
            if not self._cachedCharEffect[key] then
                local object = self._cachedCharacter[vo.characterPath[pos]]
                local effectId = checkNumber(vo.effectRootId[pos])
                if effectId > 0 then
                    ---@type TableML.TableFile
                    local tableFile = SettingMgr:Get(AutoIds.IdSetting6036)
                    ---@type TableML.TableFileRow
                    local row = tableFile:GetByPrimaryKey(effectId)
                    local effectPath = parse_string(row,"location")
                    if not isNull(effectPath) then
                        local effectPath = table.concat({NewChapterConstants.CharacterName,"/",effectPath})
                        local root = object.transform:Find(effectPath)
                        if not isNull(root) then
                            object = root
                        end
                    end
                end
                local tb = {}
                tb.effect = script[i].script
                if script[i].needCamera then
                    object = {
                        object = object,
                        camera = vo.Is2D and self.Camera2D or self.Camera3D,
                        effectCamera = self.CameraEffect,
                        effect = self.effect
                    }
                end
                tb.parameters = object
                self._cachedCharEffect[key] = tb
                script[i].script:StartEffect(object)
            end
        end
    end
end

---@param vo NewChapter2DVo
---@param pos number @characterIndex
---@return BaseEffect
function NewChapter2D:GetCharacterEffect(vo, pos)
    if string.isEmpty(vo.effect) then
        return
    end

    local t = {}
    --local sp =  string.split(vo.effect[pos], ',')
    local sp = { vo.effect[pos] }
    for i = 1, #sp do
        local effType = checkNumber(sp[i])
        if effType == NewChapterConstants.CharacterEffect.None then
            table.insert(t, "")
        else
            local script, needCamera = NewChapterShared:GetCharacterEffect(effType)
            if script == nil then
                printError("%d not impl", effType)
                table.insert(t, "")
            else
                script:Initialize(vo,effType)
                table.insert(t, { script = script, needCamera = needCamera, type = effType })
            end
        end
    end
    return t
end

function NewChapter2D:ClearCharacterEffect(vo)
    if self._cachedCharEffect == nil then
        return
    end

    for i, v in pairs(self._cachedCharEffect) do
        local isMatch = self:IsMatchKey(i,vo)
        if not isMatch then
            v.effect:RemoveEffect(v.parameters)
            self._cachedCharEffect[i] = nil
        end
    end

    if table.count(self._cachedCharEffect) > 0 then return end
    self._cachedCharEffect = nil
end

function NewChapter2D:IsMatchKey(name,vo)
    local isMatch = false
    if string.isEmpty(vo.characterId) then
        return false
    end
    for i, v in pairs(vo.characterId) do
        if string.isEmpty(vo.effect) then
            return false
        end
        if vo.effect[i] == NewChapterConstants.CharacterEffect.PhoneCall then
            return false
        end
        local key = vo.characterPath[i] .. "+" .. vo.effect[i]
        if tostring(key) == name then
            return true
        end
    end
    return isMatch
end

---@param vo NewChapter2DVo
function NewChapter2D:LoadBg(vo)

    if self.UseRealBg then
        return
    end

    if string.isEmpty(vo.sceneId) then
        if NewChapterConstants.SceneEffectImmediatelyBg[vo.screenAnim] then
            self:StartScreenEffect(vo)
        end
        return
    end

    if vo.type == NewChapterConstants.NewType.StartAnimation then
        return
    end

    if vo.sceneType == NewChapterConstants.BgType.BgMovie then

        if not KTool.IsActiveInHierarchy(self.bgMovie.gameObject) then
            KTool.SetActive(self.bgMovie.gameObject, true)
        end

        if self._cachedBgMovie == vo.sceneId then
            return
        end

        self._cachedBgMovie = vo.sceneId

        if self._cachedBgCo ~= nil then
            cs_coroutine.stop(self._cachedBgCo)
        end

        if self.bgMovie.player.status ~= CS.CriWare.CriMana.Player.Status.Playing then
            self.bgMovie.player:SetFile(nil, GameUtils.GetManaPath(vo.sceneId))
            self.bgMovie:Play()
        else

            self._cachedBgCo = cs_coroutine.start(function()
                local wait = true
                self.bgMovie.player.statusChangeCallback = function(status)
                    printInfo("status %s", tostring(status))
                    if status == CS.CriWare.CriMana.Player.Status.Stop then
                        wait = false
                    end
                end

                self.bgMovie:Stop()

                while wait do
                    coroutine.yield()
                end

                self.bgMovie.player.statusChangeCallback = nil

                printInfo("play %s", vo.sceneId)

                self.bgMovie.player:SetFile(nil, GameUtils.GetManaPath(vo.sceneId))
                self.bgMovie:Play()

                self._cachedBgCo = nil
            end)
        end
    else
        if not isNull(self.bgMovie.player) then
            self.bgMovie:Stop()
        else

        end
        if KTool.IsActiveInHierarchy(self.bgMovie.gameObject) then
            KTool.SetActive(self.bgMovie.gameObject, false)
        end

        local bg = vo.Is2D and self.bg2D or self.bg3D
        if vo.type == NewChapterConstants.NewType.StartCgPlay then
            if not KTool.IsActiveInHierarchy(self.cg.gameObject) then
                KTool.SetActive(self.cg.gameObject, true)
            end
            KTool.SetActive(self.cg, false)
            self.cg.OnFinish = function()
                KTool.SetActive(self.cg, true)
                self:StartBgScale(vo)
            end
            self.cg:LoadSprite(vo.sceneId)
        elseif vo.type == NewChapterConstants.NewType.EndCgPlay then
            if KTool.IsActiveInHierarchy(self.cg.gameObject) then
                KTool.SetActive(self.cg.gameObject, false)
            end
        elseif vo.type == NewChapterConstants.NewType.KeepCgPlay then

        else
            printInfo("LoadBg %s", vo.sceneId)
            ---@type Engine.UI.SpriteRenderAlterable
            local alterable = KTool.GetOrAddComponent(bg.gameObject, typeof(CS.Engine.UI.SpriteRenderAlterable))
            local isLoadSuccess = false
            --KTool.SetActive(bg.gameObject, false)
            alterable.OnFinish = function()
                KTool.SetActive(bg.gameObject, true)
                isLoadSuccess = true
                self:StartBgScale(vo)
                if NewChapterConstants.SceneEffectImmediatelyBg[vo.screenAnim] then
                    cs_coroutine.start(function()
                        self:StartScreenEffect(vo)
                    end)
                end
            end
            alterable:LoadSprite(vo.sceneId)
            local time = 3
            local timer = 0
            while not isLoadSuccess do
                timer = timer + 0.2
                coroutine.yield(Yielders.GetWaitForSeconds(0.2))
                if timer > time then
                    print("[剧情] 加载bg超时")
                    isLoadSuccess = true
                end
            end

            local autoFix = bg.gameObject:GetComponent(typeof(CS.PlaneAutoFix))
            if string.contains(vo.sceneId, "_cg_") then
                autoFix.DesignHeight = 720
                autoFix.DesignWidth = 1280
            else
                autoFix.DesignHeight = 840 * 0.7
                autoFix.DesignWidth = 1960 * 0.7
            end
        end
    end
    self._endWait = true
end

function NewChapter2D:LoadSceneBg(vo)
    if string.isEmpty(vo.sceneBgId) then
        KTool.SetActive(self.sceneBg.gameObject,false)
    end

    ---@type Engine.UI.SpriteRenderAlterable
    local alterable = KTool.GetOrAddComponent(self.sceneBg.gameObject, typeof(CS.Engine.UI.SpriteRenderAlterable))
    KTool.SetActive(self.sceneBg.gameObject, false)
    alterable.OnFinish = function()
        local render =  self.sceneBg.gameObject:GetComponent(typeof(SpriteRenderer))
        if isNull(render) then
            return
        end
        if not isNull(self.Tween) then
            self.Tween:Kill()
            self.Tween = nil
        end
        render.color = Color.New(1,1,1,0.5)
        KTool.SetActive(self.sceneBg.gameObject, true)
        self.Tween = render:DOColor(Color.New(1,1,1,1),1):OnComplete(function()

        end)
    end
    alterable:LoadSprite(vo.sceneBgId)
end

---@param vo NewChapter2DVo
function NewChapter2D:BgBlur(vo)
    local bg = vo.Is2D and self.bg2D or self.bg3D
    if vo.vague then
        bg.gameObject:GetComponent(typeof(SpriteRenderer)).sharedMaterial:SetFloat("_BlurRadius", 0.5)
    else
        bg.gameObject:GetComponent(typeof(SpriteRenderer)).sharedMaterial:SetFloat("_BlurRadius", 0)
    end
