---@param vo NewChapter2DVo
function NewChapter2D:BgOffsetScale(vo)
    if isNull(self.cacheSceneId) or isNull(self.bgScaleId) then
        self.cacheSceneId = vo.sceneId
        self.bgScaleId = table.concat({vo.bgScale,"_",vo.bgPivot})
        self:StartBgScale(vo)
    else
        if  (vo.sceneId ~= "" and self.cacheSceneId ~= vo.sceneId) or self.bgScaleId ~= table.concat({vo.bgScale,"_",vo.bgPivot}) then
            self.cacheSceneId = vo.sceneId
            self.bgScaleId = table.concat({vo.bgScale,"_",vo.bgPivot})
            self:StartBgScale(vo)
        end
    end
end

function NewChapter2D:StartBgScale(vo)
    local bg = vo.Is2D and self.bg2D or self.bg3D
    local pos = bg.transform.localPosition
    pos.x = 0.02
    pos.y = -0.32
    pos.z = 2.81
    bg.transform.localPosition = pos
    local autoFix = bg.gameObject:GetComponent(typeof(CS.PlaneAutoFix))
    --autoFix.ToFarClip = true
    autoFix:Adjust()

    --local dir = autoFix.FitCamera.transform.position - bg.transform.position

    if not  string.contains(vo.sceneId, "_cg_") and vo.bgScale <= 1 then
        bg.transform.localScale = Vector3(0.5, 0.5, 0.5)
    end

    if vo.bgScale > 1 then
        local scale = bg.transform.localScale
        local bgScale =  vo.bgScale * 1.7
        --vo.bgScale = vo.bgScale * 1.7
        pos = bg.transform.localPosition
        local size = CS.UnityEngine.Vector3(0,0,0)
        local offset = NewChapterConstants.BgOffset[vo.bgPivot]
        --size.x = autoFix.DesignWidth / 2 / autoFix.PixelPerUnit
        --size.y = autoFix.DesignHeight / 2 / autoFix.PixelPerUnit
        size.x = 7.46 -- 840 * 16 / 9 / 2 / 100
        size.y = 4.2  -- 840 / 100 /2
        printInfo("size (%f, %f)", size.x, size.y)
        size.x = size.x * offset.x
        size.y = size.y * offset.y
        printInfo("size (%f, %f)", size.x, size.y)
        size = size * scale.x * (bgScale - 1) * (1/1.7)
        printInfo("pivot %s, scale %s", vo.bgPivot, bgScale)
        printInfo("size (%f, %f)", size.x, size.y)
        pos = pos + size
        bg.transform.localPosition = pos
        local target = scale.x * bgScale
        scale.x = target
        scale.y = target

        bg.transform.localScale = scale
        printInfo("scale (%f, %f)", target, target)
    end
end

---@param vo NewChapter2DVo
function NewChapter2D:LoadCharacter(vo)
    if string.isEmpty(vo.characterPath)  or string.isEmpty(vo.animatorPath)  then
        return
    end

    if self._cachedCharacter == nil then
        self._cachedCharacter = {}
    end

    for i = 1, #vo.characterId do
        local path = vo.characterPath[i]
        local res = vo.characterRes[i]
        local animPath = vo.animatorPath[i]
        printInfo("load char %s", path)
        if CfUtils.IsBundleResourceExist(path) and CfUtils.IsBundleResourceExist(animPath)then
            local character
            character = self._cachedCharacter[path]
            if not KTool.IsActiveInHierarchy(character.gameObject) then
                KTool.SetActive(character.gameObject, true)
            end
            if vo.Is2D then
                NewChapterShared:LoadDicedSprite(character, path, res)
            else
                if self._cachedLoader == nil then
                    self._cachedLoader = {}
                end
                
                --self:SetCharacterState(vo, true)
                local model = NewChapterShared:GetModel(path)
                if not isNull(model) then
                    --self:SetSingleCharacterState(vo, i, true)
                    self:ApplyCharacterEffect(vo, i)
                else
                    if not isSet(self._cachedLoader, path) then
                        self._cachedLoader[path] = cs_coroutine.start(function()
                            
                            local loaders = {}
                            local loader_model = NewChapterShared:LoadModelAsync(path)
                            table.insert(loaders, loader_model)
                            
                            local needAnim = not string.isEmpty(animPath) and NewChapterShared:IsResourceExist(animPath) or false
                            if needAnim then
                                local loader_anim = NewChapterShared:LoadModelAsync(animPath)
                                table.insert(loaders, loader_anim)
                            end
                            
                            while #loaders > 0 do
                                coroutine.yield(Yielders.EndOfFrame)
                                
                                for index, loader in fipairs(loaders) do
                                    if loader.IsCompleted then
                                        table.remove(loaders, index)
                                    end
                                end
                            end
                            
                            
                            local go = NewChapterShared:GetModel(path)
                            local faceForwards = go.gameObject:GetComponentsInChildren(typeof(CS.FaceForward))
                            for i = 1, faceForwards.Length do
                                local faceForward = faceForwards[i - 1]
                                if not isNull(faceForward.TargetTransform) then
                                    KTool.GetOrAddComponent(faceForward.gameObject, typeof(CS.CustomFaceLightDir))
                                end
                            end
                            
                            local anim = NewChapterShared:GetModel(animPath)
                            self._cachedLoader[path] = nil
                            if isNull(go) then
                                return
                            end
                            local ctrl = go:GetComponent(typeof(Animator))
                            ctrl.keepAnimatorControllerStateOnDisable = true
                            
                            if needAnim then
                                ctrl.runtimeAnimatorController = anim
                            end
                            
                            go.name = NewChapterConstants.CharacterName
                            go.transform:SetParent(self._cachedCharacter[path])
                            go.transform.localPosition = Vector3.New(0, 0, 0)
                            go.transform.localScale = Vector3.New(1, 1, 1)
                            go.transform.localRotation = Quaternion.Euler(0, 0, 0)
                            
                            local script = go.gameObject:EnsureComponent(LookAtIKType)
                            if script then
                                script.enabled = false
                                script:GetIKSolver():SetLookAtWeight(0,0,0.4)
                            end
                            
                            local lookAtTarget = KTool.GetOrAddComponent(go,LookAtTarget)
                            if lookAtTarget then
                                lookAtTarget:SetTarget(self.Camera3D.transform)
                            end
                            
                            
                            self:SetReceiveShadowLight(vo.characterId[i],go)
                            
                            self:ApplyCharacterEffect(vo, i)
                        end)
                        coroutine.yield(self._cachedLoader[path])
                        printInfo("wait %s finish", path)
                        self._cachedLoader[path] = nil
                    end
                end
            end
        else
            local id = vo.characterId[i]
            if id == vo.speakId and string.isEmpty(vo.avatar) then
                if isNotNull(vo.speakIcon) then
                    self.IconHead:LoadSprite(vo.speakIcon)
                    self:SetHeadStatus(true)
                end
            end
        end
    end

    for i = 1, #vo.characterId do
        local path = vo.characterPath[i]

        if not vo.Is2D then
            ---@type NewChapterShared
            local go = NewChapterShared:GetModel(path)
            if isNotNull(go) then
                KTool.SetActive(go, true)
                local script = self._cachedCharacter[path].gameObject:EnsureComponent(typeof(CustomLightDirRelativeCamera))
                script.enabled = true
                self:StartCharacterLookAt(go,vo,i)
            end
        end
    end
    self:SetCharacterState(vo, true)
end
