function NewChapter2D:SetReceiveShadowLight(id,go)
    if self.ChapterId == 1001031 and not isNull(id) and not string.isEmpty(id) and tonumber(id) == 108008 then
        if not isNull(go) then
            local face = go.transform:Find("Unity_Export_Grp/Geometry/face")
            if not isNull(face) then
                local skinnedMeshRenderer = KTool.GetComponent(face.gameObject,typeof(CS.UnityEngine.SkinnedMeshRenderer))
                if not isNull(skinnedMeshRenderer) then
                   local mat = skinnedMeshRenderer.material
                    mat:SetFloat("_ReciveShadow",0)
                end
            end
        end
    end
end

function NewChapter2D:StartCharacterLookAt(go,vo,i)
    if not self.npcLookAtGo then
        self.npcLookAtGo = {}
    end
    local script = go.gameObject:EnsureComponent(LookAtIKType)
    local lookAtController = go.gameObject:EnsureComponent(LookAtControllerType)
    lookAtController.weightSmoothTime = 0.3
    if isSet(vo,"lookAt") and vo.lookAt[i] then
        if script then
            script.enabled = true
        end
        local tPath = string.format("83:%d_home", vo.lookAt[i])
        local searchPath = CS.ParseUtils.ParsePathNameByData(tPath, ".prefab")
        if NewChapterConstants.NpcLookAtPos[vo.lookAt[i]] then
            if not self.npcLookAtGo[vo.lookAt[i]] then
                local go = CS.UnityEngine.GameObject()
                go.name = "npcLookAtPos"..vo.lookAt[i]
                go.transform.localPosition = NewChapterConstants.NpcLookAtPos[vo.lookAt[i]]
                KTool.SetParent(go,self.Objects3D.gameObject,false)
                self.npcLookAtGo[vo.lookAt[i]] = go
            end
            lookAtController.target = self.npcLookAtGo[vo.lookAt[i]].transform
        elseif vo.lookAt[i] == 0 then
            lookAtController.target = self.Camera3D.transform
            --lookAtController.weight = 0
        elseif self._cachedCharacter[searchPath] ~= nil then
            local lookGo = self._cachedCharacter[searchPath]
            local lookTrans = lookGo.transform:Find(NewChapterConstants.IKLookAtRoot)
            if lookTrans then
                lookAtController.target = lookTrans.transform
                --lookAtController.weight = 0.45
            else
                lookAtController.target = self.Camera3D.transform
                --lookAtController.weight = 0
            end
        end
    else
        lookAtController.target = nil
        --lookAtController.weight = 0
    end
end

---@param vo NewChapter2DVo
function NewChapter2D:SetCharacterState(vo, overWrite)
    if self._cachedLoader == nil then
        return
    end

    if overWrite == nil then
        overWrite = false
    end

    if self._cachedStats == nil then
        self._cachedStats = {}
    end

    for i = 1, #vo.characterId do
        self:SetSingleCharacterState(vo, i, overWrite)
    end


end

---@param vo NewChapter2DVo
function NewChapter2D:SetSingleCharacterState(vo, i, overWrite)
    if self._cachedStats == nil then
        self._cachedStats = {}
    end

    if (not isSet(self._cachedStats, vo.characterPath[i])) or overWrite then
        local t = {}
        t.faceId = checkInt(vo.faceId[i])
        t.action = checkInt(vo.action[i])
        t.loop = vo.loop[i]
        t.position = vo.position[i]
        ---@type NewChapterPosVo
        t.offset = self.PosSetting:Get(vo.characterId[i])
        if t.offset == nil then
            printInfo("%d offset not found", vo.characterId[i])
            t.offset = NewChapterUtils.FakeOffsetVo()
        end
        t.cacheVo = vo
        self._cachedStats[vo.characterPath[i]] = t
    end

    if not isSet(self._cachedLoader, vo.characterPath[i]) then

        local go = NewChapterShared:GetModel(vo.characterPath[i])
        if isNull(go) then
            self._cachedStats[vo.characterPath[i]] = nil
            return
        end
        local anim = go.gameObject:GetComponent(typeof(Animator))
        if isNull(anim) then
            self._cachedStats[vo.characterPath[i]] = nil
            return
        end

        local t = self._cachedStats[vo.characterPath[i]]
        if t.co ~= nil then
            cs_coroutine.stop(t.co)
        end


        t.co = cs_coroutine.start(function()
            printInfo("char %d", vo.characterId[i])

            if t.action == 900101 then
                anim:SetBool("walk", true)
                anim:SetInteger("action", 0)
            else
                printInfo("set %d", t.action)
                anim:SetInteger("action", t.action)
                anim:SetBool("walk", false)
            end
            printInfo("emoji %d", t.faceId)
            anim:SetInteger("emoji", t.faceId)
        end)
    end
end

function NewChapter2D:ApplyCharacterEffect(vo, i)
    local go = NewChapterShared:GetModel(vo.characterPath[i])
    --local st = NewChapterUtils.IsCloseDis(t.position)
    --local offset = st and t.offset.close or t.offset.mid
    --go.transform.localPosition = offset
    local volume = NewChapterUtils.GetModelVolume(go)
    --NewChapterUtils.CloseFaceForward(go)
    local character = self._cachedCharacter[vo.characterPath[i]]
    character = character:Find(NewChapterConstants.MaskPath)
    local center = Vector3.New(0, volume.size.y / 2, 0)
    character.localPosition = go.transform.localPosition + center
    character.localScale = volume.size
    local cache = character.position
    cache.y = cache.y * 2
    NewChapterUtils.SetMatVectorArg(character, "_Center", cache)

    self:StartCharacterEffect(vo, i)
end

function NewChapter2D:ClearPrevCharacters(vo)
    if self._cachedCharacter == nil then
        return
    end

    for i, v in pairs(self._cachedCharacter) do
        local isHave = self:IsHaveCacheCharacter(i,vo)
        if not isHave then
            KTool.SetActive(v.gameObject, false)
        end
    end
end

function NewChapter2D:IsHaveCacheCharacter(pathName,vo)
    if string.isEmpty(vo.characterId) then
        return false
    end
    for i, v in pairs(vo.characterPath) do
        if v == pathName then
            return true
        end
    end
    return false
end

function NewChapter2D:ReposCharacters()
    if self._cachedTween == nil then
        return
    end

    for i, v in pairs(self._cachedTween) do
        for ii, vv in pairs(v) do
            if not vv:IsComplete() then
                vv:Complete()
            end
        end
    end
end

---@param vo NewChapter2DVo
function NewChapter2D:ProcessMusic(vo)
    -- print("[声音] NewChapter2D ProcessMusic", table.dump(vo, nil, 3))
    if self.soundRecord == nil then
        self.soundRecord = {}
    end

    if not string.isEmpty(vo.music) then
        --AudioManager:StopMusic()
        --AudioManager:PlayMusic(vo.music, NewChapterConstants.AudioMarker)
        --CriWareUtils.PlayMusic(vo.music[1], vo.music[2])
        if vo.music == "-1" then
            if self.soundRecord.bgm ~= nil then
                CriWareUtils.StopById(self.soundRecord.bgm)
            end
            self.soundRecord.bgm = nil
        else
            CriWareUtils.PlayMusicById(vo.music)
            self.soundRecord.bgm = vo.music
        end

        if self.soundRecord.bgmRecord == nil then
            self.soundRecord.bgmRecord = {}
        end
        table.insert(self.soundRecord.bgmRecord, vo.music)
    end

    if not string.isEmpty(vo.loopSE) then
        if vo.loopSE == "-1" then
            --AudioManager:EnsurePlaySFX(vo.loopSE, NewChapterConstants.AudioMarker)
            if self.soundRecord.loopSE ~= nil then
                CriWareUtils.StopById(self.soundRecord.loopSE)
            end
            self.soundRecord.loopSE = nil
        else
            CriWareUtils.PlaySeById(vo.loopSE)
            self.soundRecord.loopSE = vo.loopSE

            -- 现在填-1的逻辑是只关闭最后一个播放的音效（风净的需求）
            -- 所以这里把所有播放过的音效都记录下来，退出剧情的时候全都关掉
            if self.soundRecord.loopSERecord == nil then
                self.soundRecord.loopSERecord = {}
            end
            table.insert(self.soundRecord.loopSERecord, vo.loopSE)
        end
    end
end

---@param vo NewChapter2DVo
function NewChapter2D:ProcessSE(vo)
    -- print("[声音] NewChapter2D ProcessSE", table.dump(vo, nil, 3))
    --if not string.isEmpty(vo.music) then
    --    --AudioManager:StopMusic()
    --    --AudioManager:PlayMusic(vo.music, NewChapterConstants.AudioMarker)
    --    CriWareUtils.PlayMusic(vo.music[1], vo.music[2])
    --end

    if not string.isEmpty(vo.sound) then
        --AudioManager:EnsurePlaySFX(vo.sound, NewChapterConstants.AudioMarker)
        if vo.soundDelay > 0 then
            self._delaySoundCo = cs_coroutine.start(function()

                coroutine.yield(Yielders.GetWaitForSeconds(vo.soundDelay))
                CriWareUtils.PlaySeById(vo.sound)

                self._delaySoundCo = nil

            end)
        else
            CriWareUtils.PlaySeById(vo.sound)
        end

        if self.soundRecord.SERecord == nil then
            self.soundRecord.SERecord = {}
        end
        table.insert(self.soundRecord.SERecord, vo.sound)
    end



    local voice = self.gender == Constants.PLAYER_GENDER.FEMALE and vo.feVoice or vo.voice
    if string.isEmpty(voice) then
        voice = vo.voice
    end

    self.voiceFinish = false
    if not string.isEmpty(voice) then
        --AudioManager:EnsurePlaySFX(vo.voice, NewChapterConstants.AudioMarker)
        local tmp = self:GetSpeaker(vo)
        printInfo(voice)
        if self._soundDetectCo ~= nil then
            cs_coroutine.stop(self._soundDetectCo)
        end

        ---@type Engine.Lib.SoundSlice
        local slice = CriWareUtils.PlaySeById(voice, tmp)
        if not isNull(slice) then
            --slice.onFinish = function()
            --    self._modifyBs = false
            --    self._modifyModel = nil
            --    self.voiceFinish = true
            --end
            self.attachSlice = slice:GetPlayback()

            self._soundDetectCo = cs_coroutine.start(function()
                if isNull(self.attachSlice) then
                    return
                end

                while(self.attachSlice:GetStatus() ~= CriAtomExPlayback.Status.Removed) do
                    coroutine.yield(Yielders.EndOfFrame)
                end

                self._modifyBs = false
                self._modifyModel = nil
                self.voiceFinish = true

                self._soundDetectCo = nil
            end)


            if not isNull(tmp) then
                local arr = tmp.gameObject:GetComponentsInChildren(typeof(CS.UnityEngine.SkinnedMeshRenderer), true)
                self._modifyModel = {}
                for i = 1, arr.Length do
                    local model = arr[i - 1]
                    local str = model.name
                    if str == "face" or str == "mouth" then
                        local t = {}
                        t.skinned = model
                        t.willModify = {}
                        for j = 1, model.sharedMesh.blendShapeCount do
                            if NewChapterUtils.NeedModify(model.sharedMesh:GetBlendShapeName(j - 1)) then
                                table.insert(t.willModify, j - 1)
                            end
                        end
                        table.insert(self._modifyModel, t)
                    end
                    self._modifyBs = true
                end
                --printInfo("will modify %s %s", tostring(self._modifyBs), tostring(table.dump(self._modifyModel)))

            else
                self._modifyBs = false
                self._modifyModel = nil
            end

        else
            self._modifyBs = false
            self._modifyModel = nil
            self.voiceFinish = true
        end
    else
        self._modifyBs = false
        self._modifyModel = nil
        self.voiceFinish = true
    end
end

