---@param vo NewChapter2DVo
function NewChapter2D:CharacterEnter(vo)
    if string.isEmpty(vo.characterPath) then
        return
    end

    if self._cachedCharacter == nil then
        self._cachedCharacter = {}
    end

    for i = 1, #vo.characterId do
        local path = vo.characterPath[i]
        local character = self._cachedCharacter[path]

        if not isSet(self._cachedCharacter, path) then
            local searchId = ChapterUtils.ReplaceStr(path, "/", "_")
            local root = vo.Is2D and self.OBjects2D or self.Objects3D
            character = NewChapterShared:GetOrCreateTrans(searchId, vo.Is2D, root)
            self._cachedCharacter[path] = character
            local script = character.gameObject:EnsureComponent(typeof(CustomLightDirRelativeCamera))
            script.CustomLightDirection = Vector3.New(40,37,0)
            KTool.SetActive(character.gameObject, false)
            script.RelativeCamera = self.Camera3D
            script.enabled = false
        end

        local roId = string.isEmpty(vo.rotation) and 0 or vo.rotation[i]
        local enterId = string.isEmpty(vo.enter) and 0 or vo.enter[i]
        local posId = string.isEmpty(vo.position) and 0 or vo.position[i]
        ---@type NewChapterPosVo
        local offsetVo = self.PosSetting:Get(vo.characterId[i])
        if offsetVo == nil then
            printInfo("%d offset not found", vo.characterId[i])
            offsetVo = NewChapterUtils.FakeOffsetVo()
        end

        --local st = NewChapterUtils.IsCloseDis(posId)
        --local offset = st and offsetVo.close or offsetVo.mid
        --local scale = st and offsetVo.closeScale or offsetVo.midScale
        --go.transform.localPosition = offset

        local disType = NewChapterUtils.GetDisType(posId)
        local offset, scale
        if disType == NewChapterConstants.DisType.CloseDis then
            offset = offsetVo.close
            scale = offsetVo.closeScale
        elseif disType == NewChapterConstants.DisType.MidDis then
            offset = offsetVo.mid
            scale = offsetVo.midScale
        elseif disType == NewChapterConstants.DisType.MixDis then
            offset = offsetVo.mix
            scale = offsetVo.mixScale
        end

        local tb
        if vo.Is2D then
            tb = NewChapterUtils.GetEnterPos2D(posId, enterId, self.Camera2D, self.OBjects2D)
            character.localRotation = NewChapterUtils.GetCharacterRotation(roId)
        else
            tb = NewChapterUtils.GetEnterPos3D(posId, enterId, self.Camera3D, self.Objects3D)
        end
        local start = tb[1]
        local dest = tb[2]
        start = start + offset
        character.localPosition = start
        character.localScale = scale

        if not KTool.IsActiveInHierarchy(character.gameObject) then
            KTool.SetActive(character.gameObject, true)
        end

        local prevTw = self:GetTween(vo.characterPath[i])
        if not isNull(prevTw) then
            for k, v in pairs(prevTw) do
                v:Complete()
            end
            self:ClearTween(vo.characterPath[i])
        end

        local calc = start
        if dest ~= nil then
            dest = dest + offset

            local cam = vo.Is2D and self.Camera2D or self.Camera3D
            local time = NewChapterUtils.CalcMoveTime(start, dest, cam)
            local tw = character:DOLocalMove(dest, time):SetEase(NewChapterConstants.CharacterEnterParam.Ease)
            tw.stringId = "CharMove"
            self:InsertTween(vo.characterPath[i], tw)
            calc = dest

        end

--[[        if not self.characterRotateIds then
            self.characterRotateIds = {}
        end


        if not vo.Is2D and not self.characterRotateIds[vo.characterId[i]]--[[ then
            local pos = self.Camera3D.transform.position
            pos.y = character.position.y
            calc = self.Objects3D:TransformPoint(calc)
            --printInfo(pos)
            --printInfo(calc)
            local dir = pos - calc
            --printInfo(dir)
            local tmpRo = Unity_Quaternion.LookRotation(dir, CS.UnityEngine.Vector3.up).normalized
            local ro = NewChapterUtils.GetCharacterRotation(roId)
            tmpRo = Unity_Quaternion.RotateTowards(character.rotation, tmpRo, 360)
            if dest ~= nil then
                local cam = vo.Is2D and self.Camera2D or self.Camera3D
                local time = NewChapterUtils.CalcMoveTime(start, dest, cam)
                local originRo = (dest - start).normalized
                originRo = Unity_Quaternion.LookRotation(originRo, CS.UnityEngine.Vector3.up).normalized
                local preRo = Unity_Quaternion.RotateTowards(character.rotation, originRo, 360)
                local sequence = DOTween.Sequence()
                sequence:Append(character:DORotate(preRo.eulerAngles, 0.2))
                sequence:Append(DOVirtual.DelayedCall(time, function()
                    --printInfo("a")
                end))
                local fRo = tmpRo.eulerAngles + ro.eulerAngles
                sequence:Append(character:DORotate(fRo, 0.2))
            else
                printInfo(tmpRo)
                character.rotation = tmpRo
                --character.localRotation = character.localRotation + NewChapterUtils.GetCharacterRotation(vo.rotation)
                printInfo(ro)
                character.localEulerAngles = character.localEulerAngles + ro.eulerAngles
                printInfo(character.localEulerAngles)
                --local angle = tmpRo.eulerAngles + ro.eulerAngles
                --local tw = character:DORotate(angle, NewChapterConstants.CharacterRotateParam.Time):SetEase(NewChapterConstants.CharacterRotateParam.Ease)
                --tw.stringId = "CharRo"
                --self:InsertTween(vo.characterPath[i], tw)
            end
            self.characterRotateIds[vo.characterId[i]]--[[ = true
        end]]
    end
end

function NewChapter2D:InsertTween(path, tw)
    if self._cachedTween == nil then
        self._cachedTween = {}
    end
    local t = self._cachedTween[path]
    if t == nil then
        t = {}
    end
    t[tw.stringId] = tw
    self._cachedTween[path] = t

end

function NewChapter2D:GetTween(path)
    if self._cachedTween == nil then
        return nil
    end
    return self._cachedTween[path]
end

function NewChapter2D:ClearTween(path)
    if self._cachedTween == nil then
        return
    end
    self._cachedTween[path] = nil
end

---@param vo NewChapter2DVo
function NewChapter2D:ProcessItem(vo)
    local parent = self.item.transform.parent
    KTool.SetActive(parent.gameObject, true)
    KTool.SetActive(parent:Find("TextTip"), false)
    if self._cachedItem ~= vo.displayItem then
        KTool.SetActive(self.item, false)
        self.item.OnFinish = function()
            KTool.SetActive(self.item, true)
        end
        self.item.isNativeSize = true
        self.item:LoadSprite(vo.displayItem, ChapterConstants.ChapterPool)
        self._cachedItem = vo.displayItem
    end

    KTool.SetActive(self.ScreenBtn.gameObject, true)

    self._wait = true

    if not self.IsAutoPlay then
        self:SetButtonClick(self.ScreenBtn, function()
            self._wait = false
        end)
    else
        coroutine.yield(Yielders.GetWaitForSeconds(0.5))
        self._wait = false
    end

    while self._wait do
        coroutine.yield(Yielders.EndOfFrame)
    end

    self.GotoNext = vo.nextId
end

---@param vo NewChapter2DVo
function NewChapter2D:GetSpeaker(vo)
    if vo.speaker == 0 then
        return nil
    end

    local url
    for i = 1, #vo.characterId do
        if vo.characterId[i] == vo.speaker then
            url = vo.characterPath[i]
            break
        end
    end

    if url then
        return NewChapterShared:GetModel(url)
    else
        return nil
    end
end

---@param vo NewChapter2DVo
function NewChapter2D:StartMovie(vo)


    ---@type PlayerComponent
    local playerComp = ChapterUtils.GetPlayerComp()
    vo.sceneId = ChapterUtils.ReplaceStr(vo.sceneId, "#gender", playerComp.playerDojo.gender)

    KTool.SetActive(self.MovieRoot.gameObject, true)

    -- local curOP = QuestConfMgr:GetInstance():GetCurOpId()
    -- if curOP ~= Constants.QUEST_OP_LEVEL[1] then
    --     KTool.SetActive(self.Control.gameObject, false)
    -- else
    --     KTool.SetActive(self.Control.gameObject, true)
    -- end
    KTool.SetActive(self.Control.gameObject, false)

    -- 开启 字幕控件:
    if isNotNull(self.videoSubtitleEnv) then 
        CfUtils.SetActive(self.Subtitles.gameObject, true)
        self.videoSubtitleEnv:StartPlay( vo.sceneId )
    end 


    --TODO  在播放视频的时候 关闭3D相机 将UITop相机的渲染模式改为Base 暂时关闭
    KTool.SetActive(self.Camera3D.gameObject, false)
    self:SetCameraRenderType(CS.UnityEngine.Rendering.Universal.CameraRenderType.Base)

    local wait = true
    self.MovieImage.player.statusChangeCallback = function(status)
        printInfo("status %s", tostring(status))
        if status == CS.CriWare.CriMana.Player.Status.PlayEnd or status == CS.CriWare.CriMana.Player.Status.Error then
            CriWareUtils.ResetVolume(Constants.CriWareCategory.BGM)
            wait = false
        end
    end

    self.MovieImage.player:SetFile(nil, GameUtils.GetManaPath(vo.sceneId))
    self.MovieImage:Play()
    xRecord.af_internal("create_role")
    ---有一些视频不消除BGM
    if not NewChapterConstants.MovieNoSetVolume[vo.sceneId] then
        CriWareUtils.SetVolume(Constants.CriWareCategory.BGM, 0)
    end

    UIRaycastBlocker:AddCondition(vo.sceneId)


    coroutine.yield(Yielders.GetWaitForSeconds(0.5))
    self:ClearCharacterEffect(vo)
    self:ClearNormalText()
    KTool.SetActive(self.Dialog.gameObject, false)
    KTool.SetActive(self.Indicate.gameObject, false)

    --if isError then
    --    self.MovieImage:Stop()
    --    coroutine.yield(Yielders.EndOfFrame)
    --end



    while wait do
        coroutine.yield(Yielders.EndOfFrame)
    end

    self.MovieImage.player.statusChangeCallback = function(status)
        printInfo("status %s", tostring(status))
        if status == CS.CriWare.CriMana.Player.Status.Stop then
            wait = false
        end
    end

    wait = true
    self.MovieImage:Stop()


    while wait do
        coroutine.yield(Yielders.EndOfFrame)
    end

    self.MovieImage.player.statusChangeCallback = nil

    UIRaycastBlocker:RemoveCondition(vo.sceneId)

    --self._endWait = true
    KTool.SetActive(self.Control.gameObject, true)
    KTool.SetActive(self.MovieRoot.gameObject, false)


    -- 关闭字幕控件:
    if isNotNull(self.videoSubtitleEnv) then 
        self.videoSubtitleEnv:EndPlay()
        CfUtils.SetActive(self.Subtitles.gameObject, false)
    end


    self:SetCameraRenderType(CS.UnityEngine.Rendering.Universal.CameraRenderType.Overlay)
    self.GotoNext = vo.nextId

    
end

function NewChapter2D:ResetArgs()
    self._splitlineEffect = false
    self._blockWait = 0
    --self.recordCell = nil
end

function NewChapter2D:ClearEvents()
    self.ScreenBtn.onClick:RemoveAllListeners()
    self.DialogBtn.onClick:RemoveAllListeners()
end

function NewChapter2D:SetCameraRenderType(type)
    if not self.cameraData then
        self.cameraData = CameraExtensions.GetUniversalAdditionalCameraData(self.UICameraTop)
    end

    if self.cameraData.renderType == CS.UnityEngine.Rendering.Universal.CameraRenderType.Overlay 
            and type == CS.UnityEngine.Rendering.Universal.CameraRenderType.Base then
        self.UICameraTop.clearFlags = CS.UnityEngine.CameraClearFlags.SolidColor
        self.UICameraTop.backgroundColor = CS.UnityEngine.Color.black
    end
    self.cameraData.renderType = type
end


function NewChapter2D:StartEntryTip(vo)
    local data = clone(vo.EntryTip)
    self:ShowEntryTip(data)
end

function NewChapter2D:ShowEntryTip(data)
    self:StopEntryTipCo()
    if not isNull(data) and not string.isEmpty(data) and table.count(data) > 0  then
        self.entryTipCo = cs_coroutine.start(function()
            KTool.SetActive(self.EntryTipRoot.gameObject,true)
            CfUtils.SetUISwitchImage(self.EntryTipIcon,tonumber(data[1]))
            CfUtils.PlayAnimation(self.EntryTipRoot,"ChapterNormal_ChapterNewUI_IIIustbookUnlock_Entry")
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(NewChapterConstants.EntryTipShowTime))
            CfUtils.PlayAnimation(self.EntryTipRoot,"ChapterNormal_ChapterNewUI_IIIustbookUnlock_Out")
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.5))
            table.remove(data,1)
            self:ShowEntryTip(data)
        end)
    else
        KTool.SetActive(self.EntryTipRoot.gameObject,false)
    end
end

function NewChapter2D:StopEntryTipCo()
    if self.entryTipCo then
        cs_coroutine.stop(self.entryTipCo)
        self.entryTipCo = nil
        CfUtils.PlayAnimation(self.EntryTipRoot,"ChapterNormal_ChapterNewUI_IIIustbookUnlock_Out")
    end
end

function NewChapter2D:StarBattle(vo)
    if isNull(self.battleEnv) then
        self.battleEnv = CfUtils.GetLuaScr(self.ScrollingGroup.gameObject,"Game.Chapter.ChapterBattleRoot")
    end
    self.battleEnv:StartBattle(vo)
end

function NewChapter2D:ShowSkipOpTips(okCallback, cancelCallback)
    local curOP = QuestConfMgr:GetInstance():GetCurOpId()
    if curOP ~= Constants.QUEST_OP_LEVEL[4] then
        local tips = localize("<color=#ff7f50>《序章》</color>包含<color=#ff7f50>重要剧情和战斗教学</color>，请调查官确认是否需要<color=#ff7f50>跳过</color>")
        local subTips = localize("<color=#808080>提示：跳过的剧情可在主线中再次回顾</color>")
        GameUtils.SecondConfirm(tips, okCallback, cancelCallback, subTips, 14)
    else
        cancelCallback()
    end
end

function NewChapter2D:RequestSkipOp(onSuccess)
    GameUtils.Request(Interfaces.OverseaPlayerPassPrologue, nil, function(request, response)
        if checkNumber(response.errCode) == 0 then
            onSuccess()
        else
            printError("请求跳过序章失败"..tostring(checkNumber(response.errCode)))
        end
    end, function(exception)
        printError("请求跳过序章失败 "..exception.Message)
    end)
end

return NewChapter2D
